# WARNING: Under review - generated by LLM.

import hashlib
import json
import os
import re
import stat
import uuid
from dataclasses import dataclass
from datetime import datetime, timezone
from pathlib import Path
from threading import Lock
from typing import Any

from .generation import Message


_SESSION_ID = re.compile(r"[a-f0-9]{32}")
_EVENT_TYPE = re.compile(r"[a-z][a-z0-9_]{0,63}")
_MAX_EVENT_BYTES = 1024 * 1024
_MAX_LOG_BYTES = 16 * 1024 * 1024
_MAX_EVENTS = 100_000
_MAX_INSTRUCTIONS_BYTES = 64 * 1024


def _json_copy(value: Any) -> Any:
    """Validate and detach the JSON value used by a durable event."""

    try:
        return json.loads(
            json.dumps(value, ensure_ascii=True, sort_keys=True, separators=(",", ":"))
        )
    except (TypeError, ValueError) as error:
        raise ValueError("session event data must be JSON serializable") from error


def _read_regular_file(
    path: Path,
    limit: int,
    label: str,
    *,
    dir_fd: int | None = None,
    private: bool = False,
) -> tuple[bytes, tuple[int, int]]:
    """Read a bounded regular file without following a final-component symlink."""

    flags = os.O_RDONLY | getattr(os, "O_NOFOLLOW", 0)
    try:
        descriptor = os.open(path, flags, dir_fd=dir_fd)
    except OSError as error:
        raise ValueError(f"{label} does not exist or is unsafe") from error
    try:
        status = os.fstat(descriptor)
        if (
            not stat.S_ISREG(status.st_mode)
            or status.st_nlink != 1
            or status.st_size > limit
            or (private and stat.S_IMODE(status.st_mode) & 0o077 != 0)
        ):
            raise ValueError(f"{label} is invalid or too large")
        with os.fdopen(descriptor, "rb", closefd=False) as file:
            content = file.read(limit + 1)
        if len(content) > limit:
            raise ValueError(f"{label} is too large")
        return content, (status.st_dev, status.st_ino)
    finally:
        os.close(descriptor)


@dataclass(frozen=True)
class SessionEvent:
    """One immutable event in an append-only agent transcript."""

    id: str
    timestamp: str
    type: str
    parent_id: str | None
    data: dict[str, Any]

    def to_dict(self) -> dict[str, Any]:
        return _json_copy(
            {
                "id": self.id,
                "timestamp": self.timestamp,
                "type": self.type,
                "parent_id": self.parent_id,
                "data": self.data,
            }
        )

    @classmethod
    def from_dict(cls, value: Any) -> "SessionEvent":
        if not isinstance(value, dict) or set(value) != {
            "id",
            "timestamp",
            "type",
            "parent_id",
            "data",
        }:
            raise ValueError("invalid session event fields")
        event_id = value["id"]
        event_type = value["type"]
        parent_id = value["parent_id"]
        if not isinstance(event_id, str) or not _SESSION_ID.fullmatch(event_id):
            raise ValueError("invalid session event ID")
        if not isinstance(event_type, str) or not _EVENT_TYPE.fullmatch(event_type):
            raise ValueError("invalid session event type")
        if parent_id is not None and (
            not isinstance(parent_id, str) or not _SESSION_ID.fullmatch(parent_id)
        ):
            raise ValueError("invalid parent event ID")
        if not isinstance(value["timestamp"], str) or not value["timestamp"]:
            raise ValueError("invalid session event timestamp")
        if not isinstance(value["data"], dict):
            raise ValueError("invalid session event data")
        return cls(
            event_id,
            value["timestamp"],
            event_type,
            parent_id,
            _json_copy(value["data"]),
        )


class SessionLog:
    """A memory-backed or fsync-backed append-only session event stream."""

    def __init__(
        self,
        session_id: str,
        workspace: Path,
        model: str,
        *,
        path: Path | None = None,
        events: tuple[SessionEvent, ...] = (),
        identity: tuple[int, int] | None = None,
    ):
        if not _SESSION_ID.fullmatch(session_id):
            raise ValueError("invalid session ID")
        self.session_id = session_id
        self.workspace = workspace.resolve()
        self.model = model
        self.path = path
        self._identity = identity
        self._events = [SessionEvent.from_dict(event.to_dict()) for event in events]
        self._lock = Lock()

    @property
    def events(self) -> tuple[SessionEvent, ...]:
        with self._lock:
            return tuple(
                SessionEvent.from_dict(event.to_dict()) for event in self._events
            )

    @property
    def instructions(self) -> tuple[dict[str, str], ...]:
        """Return the newest recorded project-instruction snapshot."""

        snapshot: Any = ()
        for event in self.events:
            if event.type == "session_started":
                snapshot = event.data.get("instructions", ())
            elif event.type == "instructions_changed":
                snapshot = event.data.get("current", ())
        if not isinstance(snapshot, (list, tuple)):
            return ()
        return tuple(item for item in snapshot if isinstance(item, dict))

    def append(
        self, event_type: str, *, parent_id: str | None = None, **data: Any
    ) -> SessionEvent:
        """Append, flush, and fsync before making an event visible in memory."""

        if not _EVENT_TYPE.fullmatch(event_type):
            raise ValueError("invalid session event type")
        with self._lock:
            if len(self._events) >= _MAX_EVENTS:
                raise ValueError("session event limit exceeded")
            if not self._events and event_type != "session_started":
                raise ValueError("session_started must be the first event")
            if self._events and event_type == "session_started":
                raise ValueError("session metadata appears more than once")
            if parent_id is None and self._events:
                parent_id = self._events[-1].id
            elif self._events:
                if parent_id != self._events[-1].id:
                    raise ValueError("session event chain is invalid")
            elif not self._events and parent_id is not None:
                raise ValueError("session event chain is invalid")
            detached_data = _json_copy(data)
            if event_type == "tool_result":
                call_id = detached_data.get("tool_call_id")
                if call_id is not None:
                    calls = {
                        item.id for item in self._events if item.type == "tool_call"
                    }
                    completed = {
                        item.data.get("tool_call_id")
                        for item in self._events
                        if item.type == "tool_result"
                    }
                    if call_id not in calls or call_id in completed:
                        raise ValueError("tool result references an invalid call")
            event = SessionEvent(
                uuid.uuid4().hex,
                datetime.now(timezone.utc).isoformat(),
                event_type,
                parent_id,
                detached_data,
            )
            encoded = (
                json.dumps(
                    event.to_dict(),
                    ensure_ascii=True,
                    sort_keys=True,
                    separators=(",", ":"),
                )
                + "\n"
            ).encode("utf-8")
            if len(encoded) > _MAX_EVENT_BYTES:
                raise ValueError("session event is too large")
            if self.path is not None:
                flags = os.O_WRONLY | os.O_APPEND | getattr(os, "O_NOFOLLOW", 0)
                descriptor = os.open(self.path, flags)
                try:
                    status = os.fstat(descriptor)
                    if (
                        not stat.S_ISREG(status.st_mode)
                        or status.st_nlink != 1
                        or stat.S_IMODE(status.st_mode) & 0o077 != 0
                        or self._identity != (status.st_dev, status.st_ino)
                        or status.st_size + len(encoded) > _MAX_LOG_BYTES
                    ):
                        raise ValueError("session file is invalid or too large")
                    with os.fdopen(descriptor, "ab", closefd=False) as file:
                        file.write(encoded)
                        file.flush()
                        os.fsync(file.fileno())
                finally:
                    os.close(descriptor)
            self._events.append(event)
            return SessionEvent.from_dict(event.to_dict())

    def messages(self, system_prompt: str) -> list[Message]:
        """Rebuild semantic model messages without exposing audit-only events."""

        blocks = [item.get("content", "") for item in self.instructions]
        blocks = [block for block in blocks if isinstance(block, str) and block]
        if blocks:
            system_prompt += "\n\nProject instructions:\n" + "\n\n".join(blocks)
        messages: list[Message] = [{"role": "system", "content": system_prompt}]
        for event in self.events:
            content = event.data.get("content")
            if event.type == "user_message" and isinstance(content, str):
                messages.append({"role": "user", "content": content})
            elif event.type == "assistant_message" and isinstance(content, str):
                messages.append({"role": "assistant", "content": content})
            elif event.type == "tool_result" and isinstance(content, str):
                messages.append({"role": "user", "content": f"Tool result:\n{content}"})
        return messages

    def recover_unmatched_tool_calls(self) -> tuple[SessionEvent, ...]:
        """Record interruption observations without repeating an uncertain call."""

        events = self.events
        matched = {
            event.data.get("tool_call_id")
            for event in events
            if event.type == "tool_result"
        }
        recovered = []
        for event in events:
            if event.type == "tool_call" and event.id not in matched:
                recovered.append(
                    self.append(
                        "tool_result",
                        tool_call_id=event.id,
                        tool=event.data.get("tool"),
                        is_error=True,
                        content=(
                            "error: the prior process stopped before this tool call "
                            "recorded a result; it was not repeated"
                        ),
                    )
                )
        return tuple(recovered)

    def recover_incomplete_turns(self) -> tuple[SessionEvent, ...]:
        """Close crash gaps after a durable response without interpreting it."""

        recovered = list(self.recover_unmatched_tool_calls())
        events = self.events
        protocol_events = {
            "assistant_message",
            "tool_call",
            "tool_result",
            "run_finished",
            "run_started",
            "user_message",
        }
        for index, event in enumerate(events):
            if event.type != "assistant_message":
                continue
            following = next(
                (
                    candidate
                    for candidate in events[index + 1 :]
                    if candidate.type in protocol_events
                ),
                None,
            )
            if following is None or following.type in {
                "assistant_message",
                "run_started",
                "user_message",
            }:
                recovered.append(
                    self.append(
                        "tool_result",
                        tool_call_id=None,
                        tool=None,
                        is_error=True,
                        content=(
                            "error: the prior process stopped after recording a "
                            "model response; no action from it was repeated"
                        ),
                    )
                )
        return tuple(recovered)


class SessionStore:
    """Create and resume workspace-bound local session transcripts."""

    def __init__(self, workspace: Path, model: str):
        self.workspace = workspace.resolve()
        self.model = model
        self.directory = self.workspace / ".tiny-llm" / "sessions"

    def _ensure_directory(self) -> None:
        descriptor = self._open_directory(create=True)
        os.close(descriptor)

    def _open_directory(self, *, create: bool) -> int:
        flags = (
            os.O_RDONLY | getattr(os, "O_DIRECTORY", 0) | getattr(os, "O_NOFOLLOW", 0)
        )
        root = os.open(self.workspace, flags)
        parent = None
        try:
            parent_created = False
            if create:
                try:
                    os.mkdir(".tiny-llm", 0o700, dir_fd=root)
                    parent_created = True
                except FileExistsError:
                    pass
            if parent_created:
                os.fsync(root)
            parent = os.open(".tiny-llm", flags, dir_fd=root)
            if not stat.S_ISDIR(os.fstat(parent).st_mode):
                raise ValueError("session path is unsafe")
            os.fchmod(parent, 0o700)
            directory_created = False
            if create:
                try:
                    os.mkdir("sessions", 0o700, dir_fd=parent)
                    directory_created = True
                except FileExistsError:
                    pass
            if directory_created:
                os.fsync(parent)
            directory = os.open("sessions", flags, dir_fd=parent)
            if not stat.S_ISDIR(os.fstat(directory).st_mode):
                os.close(directory)
                raise ValueError("session path is unsafe")
            os.fchmod(directory, 0o700)
            return directory
        except OSError as error:
            raise ValueError("session path is unsafe") from error
        finally:
            if parent is not None:
                os.close(parent)
            os.close(root)

    def _fsync_directory(self, descriptor: int | None = None) -> None:
        owned = descriptor is None
        if descriptor is None:
            descriptor = self._open_directory(create=False)
        try:
            os.fsync(descriptor)
        finally:
            if owned:
                os.close(descriptor)

    def _instructions(self) -> tuple[dict[str, str], ...]:
        flags = (
            os.O_RDONLY | getattr(os, "O_DIRECTORY", 0) | getattr(os, "O_NOFOLLOW", 0)
        )
        root = os.open(self.workspace, flags)
        try:
            try:
                content, _ = _read_regular_file(
                    Path("AGENTS.md"),
                    _MAX_INSTRUCTIONS_BYTES,
                    "AGENTS.md",
                    dir_fd=root,
                )
            except ValueError as error:
                try:
                    os.stat("AGENTS.md", dir_fd=root, follow_symlinks=False)
                except FileNotFoundError:
                    return ()
                raise error
        finally:
            os.close(root)
        text = content.decode("utf-8")
        return (
            {
                "path": "AGENTS.md",
                "sha256": hashlib.sha256(content).hexdigest(),
                "content": text,
            },
        )

    def create(self, session_id: str | None = None) -> SessionLog:
        instructions = self._instructions()
        session_id = session_id or uuid.uuid4().hex
        if not _SESSION_ID.fullmatch(session_id):
            raise ValueError("invalid session ID")
        directory = self._open_directory(create=True)
        path = self.directory / f"{session_id}.jsonl"
        temporary = self.directory / f".{session_id}-{uuid.uuid4().hex}.tmp"
        flags = os.O_WRONLY | os.O_CREAT | os.O_EXCL | getattr(os, "O_NOFOLLOW", 0)
        try:
            descriptor = os.open(temporary.name, flags, 0o600, dir_fd=directory)
        except BaseException:
            os.close(directory)
            raise
        status = os.fstat(descriptor)
        os.close(descriptor)
        log = SessionLog(
            session_id,
            self.workspace,
            self.model,
            path=temporary,
            identity=(status.st_dev, status.st_ino),
        )
        linked = False
        try:
            log.append(
                "session_started",
                session_id=session_id,
                workspace=str(self.workspace),
                model=self.model,
                instructions=instructions,
            )
            os.link(
                temporary.name,
                path.name,
                src_dir_fd=directory,
                dst_dir_fd=directory,
                follow_symlinks=False,
            )
            linked = True
            os.unlink(temporary.name, dir_fd=directory)
            log.path = path
            self._fsync_directory(directory)
        except BaseException:
            try:
                os.unlink(temporary.name, dir_fd=directory)
            except FileNotFoundError:
                pass
            if linked:
                try:
                    os.unlink(path.name, dir_fd=directory)
                except FileNotFoundError:
                    pass
            self._fsync_directory(directory)
            raise
        finally:
            os.close(directory)
        return log

    @staticmethod
    def _validate_events(events: list[SessionEvent]) -> None:
        if not events or events[0].type != "session_started":
            raise ValueError("session metadata is missing")
        if events[0].parent_id is not None:
            raise ValueError("session event chain is invalid")
        calls: set[str] = set()
        results: set[str] = set()
        for index, event in enumerate(events):
            if index and event.type == "session_started":
                raise ValueError("session metadata appears more than once")
            if index and event.parent_id != events[index - 1].id:
                raise ValueError("session event chain is invalid")
            if event.type == "tool_call":
                calls.add(event.id)
            elif event.type == "tool_result":
                call_id = event.data.get("tool_call_id")
                if call_id is not None:
                    if call_id not in calls or call_id in results:
                        raise ValueError("tool result references an invalid call")
                    results.add(call_id)

    def _recover_publication(self, directory: int, name: str) -> None:
        """Finish the link publication if a crash left its private name."""

        try:
            status = os.stat(name, dir_fd=directory, follow_symlinks=False)
        except FileNotFoundError as error:
            raise ValueError("session file does not exist or is unsafe") from error
        if status.st_nlink == 1:
            return
        prefix = f".{Path(name).stem}-"
        matches = []
        for candidate in os.listdir(directory):
            if not candidate.startswith(prefix) or not candidate.endswith(".tmp"):
                continue
            candidate_status = os.stat(
                candidate, dir_fd=directory, follow_symlinks=False
            )
            if (candidate_status.st_dev, candidate_status.st_ino) == (
                status.st_dev,
                status.st_ino,
            ):
                matches.append(candidate)
        if status.st_nlink != 2 or len(matches) != 1:
            raise ValueError("session file has an unsafe link count")
        os.unlink(matches[0], dir_fd=directory)
        os.fsync(directory)

    def load(self, session_id: str) -> SessionLog:
        if not _SESSION_ID.fullmatch(session_id):
            raise ValueError("invalid session ID")
        path = self.directory / f"{session_id}.jsonl"
        directory = self._open_directory(create=False)
        try:
            self._recover_publication(directory, path.name)
            content, identity = _read_regular_file(
                Path(path.name),
                _MAX_LOG_BYTES,
                "session file",
                dir_fd=directory,
                private=True,
            )
        finally:
            os.close(directory)
        if content and not content.endswith(b"\n"):
            raise ValueError("session file ends with a partial event")
        events = []
        seen = set()
        for number, line in enumerate(content.splitlines(), 1):
            if number > _MAX_EVENTS or len(line) > _MAX_EVENT_BYTES:
                raise ValueError("session event limit exceeded")
            try:
                event = SessionEvent.from_dict(json.loads(line))
            except (UnicodeDecodeError, json.JSONDecodeError) as error:
                raise ValueError(f"invalid session JSONL line {number}") from error
            if event.id in seen:
                raise ValueError("duplicate session event ID")
            seen.add(event.id)
            events.append(event)
        self._validate_events(events)
        metadata = events[0].data
        if metadata.get("session_id") != session_id:
            raise ValueError("session metadata ID does not match its filename")
        if metadata.get("workspace") != str(self.workspace):
            raise ValueError("session belongs to a different workspace")
        if metadata.get("model") != self.model:
            raise ValueError("session belongs to a different model")
        log = SessionLog(
            session_id,
            self.workspace,
            self.model,
            path=path,
            events=tuple(events),
            identity=identity,
        )
        current = self._instructions()
        if current != log.instructions:
            log.append(
                "instructions_changed", previous=log.instructions, current=current
            )
        log.recover_incomplete_turns()
        return log

    def latest(self) -> SessionLog:
        directory = self._open_directory(create=False)
        try:
            candidates = []
            for name in os.listdir(directory):
                path = Path(name)
                if path.suffix != ".jsonl" or not _SESSION_ID.fullmatch(path.stem):
                    continue
                status = os.stat(name, dir_fd=directory, follow_symlinks=False)
                if stat.S_ISREG(status.st_mode):
                    candidates.append((status.st_mtime_ns, name))
            candidates.sort(reverse=True)
            if not candidates:
                raise ValueError("no saved session exists")
            for _, name in candidates:
                self._recover_publication(directory, name)
                content, _ = _read_regular_file(
                    Path(name),
                    _MAX_LOG_BYTES,
                    "session file",
                    dir_fd=directory,
                    private=True,
                )
                first_line = content.splitlines()[:1]
                if not first_line:
                    raise ValueError("session metadata is missing")
                try:
                    metadata = SessionEvent.from_dict(json.loads(first_line[0]))
                except (UnicodeDecodeError, json.JSONDecodeError) as error:
                    raise ValueError("invalid session metadata") from error
                if metadata.type != "session_started":
                    raise ValueError("session metadata is missing")
                if metadata.data.get("session_id") != Path(name).stem:
                    raise ValueError("session metadata ID does not match its filename")
                if metadata.data.get("workspace") != str(self.workspace):
                    raise ValueError("session belongs to a different workspace")
                if metadata.data.get("model") == self.model:
                    selected = Path(name).stem
                    break
            else:
                raise ValueError("no saved session exists for this model")
        finally:
            os.close(directory)
        return self.load(selected)


def memory_session(workspace: Path, model: str) -> SessionLog:
    """Create an event log that never writes a transcript to disk."""

    store = SessionStore(workspace, model)
    log = SessionLog(uuid.uuid4().hex, store.workspace, model)
    log.append(
        "session_started",
        session_id=log.session_id,
        workspace=str(store.workspace),
        model=model,
        instructions=store._instructions(),
    )
    return log
